        try_merge(i, j)

    routes = [r for r in routes if r]
    route_of = {}
    demands_of_route = []
    for idx, r in enumerate(routes):
        demands_of_route.append(route_demand(r))
        for c in r:
            route_of[c] = idx

    # ---- One repair phase: ensure feasibility and full coverage deterministically ----
    assigned = set()
    for r in routes:
        for c in r:
            assigned.add(c)
    missing = [c for c in all_customers if c not in assigned]

    # also, in case of any inconsistencies, remove duplicates within a route deterministically
    # (keep first occurrence order)
    for ridx in range(len(routes)):
        seen_local = set()
        newr = []
        for c in routes[ridx]:
            if c in seen_local:
                continue
            seen_local.add(c)
            newr.append(c)
        routes[ridx] = newr

    # rebuild after duplicate cleanup
    route_of = {}
    demands_of_route = []
    for idx, r in enumerate(routes):
        demands_of_route.append(route_demand(r))
        for c in r:
            route_of[c] = idx

    for c in missing:
        best_idx = None
        best_pos = None
        best_delta = 10**30
        best_newdemand = None
        for idx, r in enumerate(routes):
            if demands_of_route[idx] + demand[c] <= cap:
                pos, delta = best_insertion_pos(r, c)
                if delta < best_delta:
                    best_delta = delta
                    best_idx = idx
                    best_pos = pos
                    best_newdemand = demands_of_route[idx] + demand[c]
        if best_idx is None:
            routes.append([c])
            demands_of_route.append(demand[c])
            route_of[c] = len(routes) - 1
        else:
            routes[best_idx].insert(best_pos, c)
            demands_of_route[best_idx] = best_newdemand
            route_of[c] = best_idx

    # Final safeguard: move any infeasible customers by reinsertion (deterministic)
    # If a route exceeds cap due to any unforeseen issue, rebuild it by greedy insertion from its contents.
    for ridx in range(len(routes)):
        r = routes[ridx]
        if route_demand(r) <= cap:
            continue
        # rebuild route: keep first feasible subsequence by deterministic order,
        # then reassign excess to other feasible routes (or new routes).
        kept = []
        kept_load = 0
        overflow = []
        for c in r:
            if kept_load + demand[c] <= cap:
                kept.append(c)
                kept_load += demand[c]
            else:
                overflow.append(c)

        routes[ridx] = kept
        demands_of_route[ridx] = kept_load
        for c in kept:
            route_of[c] = ridx

        for c in overflow:
            assigned_now = False
            for idx in range(len(routes)):
                if demands_of_route[idx] + demand[c] <= cap:
                    pos, delta = best_insertion_pos(routes[idx], c)
                    # choose first feasible deterministically; tie-break by delta
                    if (not assigned_now) or delta < best_delta:
                        best_delta = delta
                        best_idx = idx
                        best_pos = pos
                    assigned_now = True
            if not assigned_now:
                routes.append([c])
                demands_of_route.append(demand[c])
                route_of[c] = len(routes) - 1
            else:
                routes[best_idx].insert(best_pos, c)
                demands_of_route[best_idx] += demand[c]
                route_of[c] = best_idx

    # Ensure no depot in routes (by construction it isn't)
    return routes
